package com.daytracker.tasks;

import java.time.LocalDate;
import java.util.UUID;

import jakarta.validation.constraints.NotNull;

/**
 * The id is generated by the client so a retried create is idempotent.
 * Title and description lengths are checked by the service after trimming.
 */
public record CreateTaskRequest(@NotNull UUID id, @NotNull String title, String description, UUID categoryId,
		TaskPriority priority, LocalDate plannedDate, LocalDate deadlineDate) {
}
